const pixelSource = source.replace(/\{field\('订单来源',<ForgeSelect[\s\S]*?\/\>\)\}/, `<div className="fp-field span-all"><label>订单来源</label><div className="order-source-grid"><button type="button" className={'order-source-card '+(form.source_type==='direct'?'active':'')} onClick={()=>change('source_type','direct')}><strong>⚡ 直接新建</strong><span>独立订单，不关联合同。适用于普通成交、一次性业务。</span></button><button type="button" className={'order-source-card '+(form.source_type==='contract'?'active':'')} onClick={()=>change('source_type','contract')}><strong>▤ 关联合同</strong><span>关联已签订合同，引用价格/条款/规则，并按合同约定控制订单金额。</span></button></div></div>`);
const pixelSourceStructured = pixelSource.replace(/<section className="fp-card order-section"><div className="order-section-head"><h2>订单来源与基本信息<\/h2><\/div><div className="order-section-body order-grid">[\s\S]*?<\/div><\/section>/, `<section className="fp-card order-section"><div className="order-section-head"><h2 className="order-section-heading"><span>▱</span><span>订单来源</span><small>· 决定订单与合同关系和统计口径</small></h2></div><div className="order-section-body"><div className="order-source-grid"><button type="button" className={'order-source-card '+(form.source_type==='direct'?'active':'')} onClick={()=>change('source_type','direct')}><strong>⚡ 直接新建</strong><span>独立订单，不关联合同。适用于普通成交、一次性业务。</span></button><button type="button" className={'order-source-card '+(form.source_type==='contract'?'active':'')} onClick={()=>change('source_type','contract')}><strong>▤ 关联合同</strong><span>关联已签订合同，引用其价格/账期/规则。若合同约定总金额或单品数量上限，超出时订单进入审批。</span></button></div></div></section><section className="fp-card order-section"><div className="order-section-head"><h2>订单基本信息</h2><span className="fp-secondary">0/8</span></div><div className="order-section-body order-grid order-basic-grid">{field('订单名称',<input className="fp-input" aria-label="订单名称" placeholder="请输入订单名称" value={form.name} onChange={event=>change('name',event.target.value)}/>)}{field('客户单号',<input className="fp-input" aria-label="客户单号" placeholder="请输入客户单号" value={form.customer_po_number} onChange={event=>change('customer_po_number',event.target.value)}/>)}{field('客户 *',<ForgeSelect label="客户" value={form.customer_id} onChange={value=>change('customer_id',value)} options={data.customers.map(item=>({value:item.id,label:item.name}))} placeholder="搜索客户名称..."/>)}{field('客户联系人',<ForgeSelect label="客户联系人" value={form.contact_id} onChange={value=>change('contact_id',value)} options={contacts.map(item=>({value:item.id,label:item.name+(item.phone?' · '+item.phone:'')}))} placeholder={form.customer_id?'请选择联系人':'请先选择客户'} disabled={!form.customer_id}/>)}{field('联系电话',<input className="fp-input" aria-label="联系电话" placeholder="请输入联系电话" value={form.delivery_phone} onChange={event=>change('delivery_phone',event.target.value)}/>)}{field('计划交货日期 *',<ForgeDateInput className="fp-input" aria-label="计划交货日期" value={form.planned_delivery_on} onChange={event=>change('planned_delivery_on',event.target.value)}/>)}{field('收货地址',<input className="fp-input" aria-label="收货地址" placeholder={form.customer_id?'请输入收货地址':'请先选择客户'} value={form.delivery_address} onChange={event=>change('delivery_address',event.target.value)} disabled={!form.customer_id}/>,true)}{field('收货人',<input className="fp-input" aria-label="收货人" value={form.delivery_contact} onChange={event=>change('delivery_contact',event.target.value)}/>)}{field('订单备注',<textarea className="fp-textarea" aria-label="订单备注" placeholder="订单备注信息..." value={form.remarks} onChange={event=>change('remarks',event.target.value)}/>,true)}</div></section>`);
const pixelSourceWithAccount = pixelSourceStructured.replace("{field('客户联系人',", "{field('公司账户',<ForgeSelect label=\"公司账户\" value={form.company_account_id} onChange={value=>change('company_account_id',value)} options={data.accounts.map(item=>({value:item.id,label:display(data.accounts,item.id)}))} placeholder=\"选择公司账户\"/>)}{field('客户联系人',");
